  const ADULT_AVATARS = ["mom", "dad", "grandma", "grandpa", "adult", "hero", "aunt", "uncle", "teacher", "abuela"];
  const FROM_EMOJI = { "🦊": "fox", "🐼": "panda", "🦁": "lion", "🐸": "frog", "🦄": "unicorn", "🐙": "octopus", "🐯": "cat", "🐨": "bear", "🦖": "dino", "🐧": "penguin", "🚀": "owl", "🧑‍🚀": "bunny", "🙂": "bunny", "👩": "mom", "👨": "dad", "👵": "grandma", "👴": "grandpa", "🧑": "adult", "🦸": "hero" };
  const avatarId = (v) => (AV[v] ? v : FROM_EMOJI[v] || null);
  let clipN = 0;
  const avatar = (v) => { if (typeof v === "string" && v.startsWith("c:")) { const id = "avc" + (++clipN); return `<svg class="avi" viewBox="0 0 64 64" role="img" aria-label="Avatar"><defs><clipPath id="${id}"><circle cx="32" cy="32" r="32"/></clipPath></defs><g clip-path="url(#${id})">${custom(parseC(v))}</g></svg>`; } const id = avatarId(v); return id ? `<svg class="avi" viewBox="0 0 64 64" role="img" aria-label="Avatar">${AV[id]}</svg>` : `<span class="avi">${v || ""}</span>`; };

  /* ---------- álbum de stickers (100×100) ---------- */
  const K = "#3c3c3c";
  const fx = (n) => +n.toFixed(2);
  const sE = (x, y, r = 3.6) => `<circle cx="${x}" cy="${y}" r="${r}" fill="${K}"/><circle cx="${fx(x + r * .32)}" cy="${fx(y - r * .36)}" r="${fx(r * .36)}" fill="#fff"/>`;
  const sEyes = (x1, x2, y, r) => sE(x1, y, r) + sE(x2, y, r);
  const sSmile = (x, y, w = 5, c = K, sw = 2.6) => `<path d="M${fx(x - w)} ${fx(y)} Q${fx(x)} ${fx(y + w)} ${fx(x + w)} ${fx(y)}" stroke="${c}" stroke-width="${fx(sw)}" fill="none" stroke-linecap="round"/>`;
  const sBlush = (x1, x2, y, r = 3.6) => `<circle cx="${fx(x1)}" cy="${fx(y)}" r="${fx(r)}" fill="#ff8fa3" opacity=".6"/><circle cx="${fx(x2)}" cy="${fx(y)}" r="${fx(r)}" fill="#ff8fa3" opacity=".6"/>`;
  const sFace = (cx, cy, s = 1, c = K) => sEyes(fx(cx - 7 * s), fx(cx + 7 * s), cy, fx(3.2 * s)) + sSmile(cx, cy + 6 * s, 4 * s, c, 2.4 * s) + sBlush(cx - 12 * s, cx + 12 * s, cy + 4.5 * s, 3 * s);
  const starPts = (cx, cy, R, r, n = 5, rot = -90) => Array.from({ length: n * 2 }, (_, i) => { const a = (rot + i * 180 / n) * Math.PI / 180, d = i % 2 ? r : R; return `${fx(cx + d * Math.cos(a))},${fx(cy + d * Math.sin(a))}`; }).join(" ");
  const sStar = (cx, cy, R, fill, r = R * .5, extra = "") => `<polygon points="${starPts(cx, cy, R, r)}" fill="${fill}" ${extra}/>`;
  const sSpark = (cx, cy, s, fill = "#fff") => { const q = fx(s * .18); return `<path d="M${cx} ${fx(cy - s)} Q${fx(cx + q)} ${fx(cy - q)} ${fx(cx + s)} ${cy} Q${fx(cx + q)} ${fx(cy + q)} ${cx} ${fx(cy + s)} Q${fx(cx - q)} ${fx(cy + q)} ${fx(cx - s)} ${cy} Q${fx(cx - q)} ${fx(cy - q)} ${cx} ${fx(cy - s)}Z" fill="${fill}"/>`; };
  const pac = (cx, cy, r, dir, open, fill) => { const a1 = (dir + open) * Math.PI / 180, a2 = (dir - open) * Math.PI / 180; return `<path d="M${cx} ${cy} L${fx(cx + r * Math.cos(a1))} ${fx(cy + r * Math.sin(a1))} A${r} ${r} 0 1 1 ${fx(cx + r * Math.cos(a2))} ${fx(cy + r * Math.sin(a2))}Z" fill="${fill}"/>`; };
  const circ = (cx, cy, r) => `M${cx - r} ${cy} a${r} ${r} 0 1 0 ${2 * r} 0 a${r} ${r} 0 1 0 ${-2 * r} 0Z`;
  const regPoly = (cx, cy, r, n, rot = -90) => Array.from({ length: n }, (_, i) => { const a = (rot + i * 360 / n) * Math.PI / 180; return `${fx(cx + r * Math.cos(a))},${fx(cy + r * Math.sin(a))}`; }).join(" ");
  const gear = (cx, cy, r, n, fill) => `<g fill="${fill}">${Array.from({ length: n }, (_, i) => `<rect x="${fx(cx - r * .2)}" y="${fx(cy - r * 1.3)}" width="${fx(r * .4)}" height="${fx(r * .5)}" rx="${fx(r * .1)}" transform="rotate(${fx(i * 360 / n)} ${cx} ${cy})"/>`).join("")}<circle cx="${cx}" cy="${cy}" r="${r}"/></g>`;
  const spiral = (cx, cy, r0, k, turns) => { let d = ""; for (let i = 0; i <= turns * 36; i++) { const t = i / 36 * 2 * Math.PI, r = r0 + k * t; d += (i ? " L" : "M") + fx(cx + r * Math.cos(t)) + " " + fx(cy + r * Math.sin(t)); } return d; };
  const fit = (s, body, cx = 50, cy = 52) => `<g transform="translate(${cx} ${cy}) scale(${s}) translate(${-cx} ${-cy})">${body}</g>`;
