    /* deportes y diversión */
    s61: () => { let s = `<circle cx="50" cy="52" r="31" fill="#fff" stroke="${K}" stroke-width="2.6"/><polygon points="${regPoly(50, 52, 9, 5)}" fill="${K}"/>`, l = ""; for (let i = 0; i < 5; i++) { const a = (-90 + i * 72) * Math.PI / 180, b = (-90 + 36 + i * 72); l += `M${fx(50 + 9 * Math.cos(a))} ${fx(52 + 9 * Math.sin(a))} L${fx(50 + 18 * Math.cos(a))} ${fx(52 + 18 * Math.sin(a))} `; s += `<polygon points="${regPoly(fx(50 + 23.5 * Math.cos(b * Math.PI / 180)), fx(52 + 23.5 * Math.sin(b * Math.PI / 180)), 6, 5, b)}" fill="${K}"/>`; } return s + `<path d="${l}" stroke="${K}" stroke-width="2.2"/><ellipse cx="38" cy="34" rx="6" ry="3.4" fill="#fff" opacity=".7" transform="rotate(-35 38 34)"/>`; },
