    s63: () => { const cx = 46, cy = 38, rx = 19, ry = 23; let s = ""; for (let x = cx - 14; x <= cx + 14; x += 7) { const h = ry * Math.sqrt(1 - ((x - cx) / rx) ** 2); s += `M${x} ${fx(cy - h)} V${fx(cy + h)} `; } for (let y = cy - 18; y <= cy + 18; y += 6) { const w = rx * Math.sqrt(1 - ((y - cy) / ry) ** 2); s += `M${fx(cx - w)} ${y} H${fx(cx + w)} `; } return `<g transform="rotate(-28 46 52)"><rect x="43" y="61" width="6" height="12" fill="#8fa4ae"/><rect x="42" y="72" width="8" height="18" rx="3" fill="#a0673a"/><path d="${s}" stroke="#dfe7ee" stroke-width="1.4"/><ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="none" stroke="#ff4b4b" stroke-width="4.5"/></g><circle cx="72" cy="72" r="11" fill="#d7f205"/><path d="M62 68 Q72 72 70 82 M82 76 Q72 72 74 62" stroke="#fff" stroke-width="2" fill="none" stroke-linecap="round"/>`; },
